function normalizarTelefonoArgentina(numero) {
  if (!numero) return null;
  let d = String(numero).replace(/\D/g, '');
  if (d.startsWith('549') && d.length === 13) return d;
  if (d.startsWith('54') && d.length === 12) return '549' + d.slice(2);
  if (d.startsWith('0')) d = d.slice(1);
  if (d.startsWith('1115') && d.length === 12) d = '11' + d.slice(4);
  if (d.length === 10) return '549' + d;
  return null;
}
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/\s+/g, ' ').trim();

// Webhook Pilot -> campaña de la suite según pilot_negocio (FIAT/PEUGEOT x plan/0km)
const body = $input.first().json.body || {};
const negocio = String(body.pilot_negocio || body.negocio || '').trim();
const nombre = [body.pilot_firstname, body.pilot_lastname].filter(v => v && String(v).trim()).map(v => String(v).trim()).join(' ') || 'Cliente';

let telefono = body.pilot_cellphone || body.pilot_phone || null;
if (!telefono && body.pilot_notes) {
  const m = String(body.pilot_notes).match(/n[uú]mero_de_whatsapp:\s*([+\d\s()-]+)/i);
  if (m) telefono = m[1].trim();
}
const phone = normalizarTelefonoArgentina(telefono);

const n = norm(negocio);
const fiat = n.includes('FIAT'), peugeot = n.includes('PEUGEOT');
const plan = n.includes('AHORRO') || n.includes('PLAN');
const okm = /(^|\s)0\s*KM(\s|$)/.test(n) || n.includes('0KM');

// Campañas de la suite. La variable del campaign_id la inyecta la suite: no se manda.
// Imagen por marca: concesionaria FIAT / concesionaria Peugeot.
const IMG_FIAT = 'Fiat-1878_20251028_100924.jpg';
const IMG_PEUGEOT = 'WhatsApp-Image-2025-07-14-at-12.32.12-PM_20251110_100927.jpeg';
const c = [
  { ok: fiat && plan, id: 5978, label: 'nocomprafiatplansinmodelo', img: IMG_FIAT },
  { ok: peugeot && plan, id: 5979, label: 'nocomprapeugeotplansinmodelo', img: IMG_PEUGEOT },
  { ok: fiat && okm, id: 5976, label: 'nocomprafiatconvencionalsinmodelo', img: IMG_FIAT },
  { ok: peugeot && okm, id: 5980, label: 'nocomprapeugeotconvencionalsinmodelo', img: IMG_PEUGEOT },
].find(x => x.ok) || null;

return [{ json: {
  valido: Boolean(phone && c),
  campaign_id: c ? c.id : 0,
  campana: c ? c.label : null,
  phone_number: phone,
  telefono_original: telefono,
  negocio,
  variables: c ? { '1': nombre, '2': c.img } : {},
} }];

